// Checkout.test.tsx
import { render, screen, within } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { vi, describe, it, expect, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - yes, I DID explain this yesterday
const mockCart = {
  items: [{ id: '1', name: 'Widget', price: 29.99 }],
  total: 29.99,
  clearCart: vi.fn()
};
const mockProcessPayment = vi.fn();

vi.mock('./CartContext', () => ({
  useCart: () => mockCart
}));
vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

describe('Checkout Component', () => {
  const user = userEvent.setup();

  beforeEach(() => {
    vi.clearAllMocks();
    mockCart.items = [{ id: '1', name: 'Widget', price: 29.99 }];
  });

  // HAPPY PATH - Hex says this is the "interesting" one
  describe('complete checkout flow', () => {
    it('navigates shipping → payment → review → confirmation', async () => {
      mockProcessPayment.mockResolvedValue({ orderId: 'ORD-12345' });
      render(<Checkout />);

      // Arrange/Act: Shipping
      await user.type(screen.getByLabelText(/street address/i), '123 Unseen Lane');
      await user.type(screen.getByLabelText(/city/i), 'Ankh-Morpork');
      await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
      await user.type(screen.getByLabelText(/zip code/i), '90210');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      // Assert: Now on payment
      expect(screen.getByRole('heading', { name: /payment details/i })).toBeInTheDocument();

      // Act: Payment
      await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
      await user.type(screen.getByLabelText(/expiry/i), '12/25');
      await user.type(screen.getByLabelText(/cvv/i), '123');
      await user.type(screen.getByLabelText(/name on card/i), 'Rincewind');
      await user.click(screen.getByRole('button', { name: /review order/i }));

      // Assert: Review displays correctly
      expect(screen.getByText(/widget/i)).toBeInTheDocument();
      expect(screen.getByText(/1111/)).toBeInTheDocument(); // Last 4 digits

      // Act: Place order
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Assert: Confirmation
      expect(await screen.findByText(/order confirmed/i)).toBeInTheDocument();
      expect(screen.getByText('ORD-12345')).toBeInTheDocument();
    });
  });

  // VALIDATION - Out Of Cheese Error territory
  describe('form validation', () => {
    it('shows inline errors for invalid shipping fields', async () => {
      render(<Checkout />);
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
      expect(screen.getByLabelText(/street address/i)).toHaveAttribute('aria-invalid', 'true');
    });

    it('validates ZIP code format', async () => {
      render(<Checkout />);
      await user.type(screen.getByLabelText(/zip code/i), 'MELON');
      await user.click(screen.getByRole('button', { name: /continue to payment/i }));

      expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
    });
  });

  // EDGE CASES - The bits senior wizards never think about
  describe('edge cases', () => {
    it('displays empty cart message when no items', () => {
      mockCart.items = [];
      render(<Checkout />);

      expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
    });

    it('handles payment failure with error recovery', async () => {
      mockProcessPayment.mockRejectedValue(new Error('Card declined'));
      // ...navigate to review step, then:

      expect(await screen.findByRole('alert')).toHaveTextContent(/card declined/i);
      expect(screen.getByRole('button', { name: /place order/i })).toBeEnabled();
    });
  });

  // ACCESSIBILITY - It's not magic if you understand ARIA
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    expect(await axe(container)).toHaveNoViolations();
  });
});
